{
  "meta": {
    "name": "Event Booking Platform",
    "description": "A platform for organizers to create events and for attendees to reserve tickets, with premium features for organizers."
  },
  "entities": [
    {
      "name": "Event",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "date",
          "type": "date",
          "required": true
        },
        {
          "name": "time",
          "type": "string",
          "required": true
        },
        {
          "name": "location",
          "type": "string",
          "required": true
        },
        {
          "name": "capacity",
          "type": "integer",
          "required": true
        },
        {
          "name": "isFeatured",
          "type": "boolean",
          "default": false
        }
      ]
    },
    {
      "name": "Ticket",
      "ownable": true,
      "fields": [
        {
          "name": "type",
          "type": "string",
          "required": true
        },
        {
          "name": "price",
          "type": "number",
          "required": true
        },
        {
          "name": "quantity",
          "type": "integer",
          "required": true,
          "default": 1
        }
      ],
      "relations": [
        {
          "name": "event",
          "kind": "manyToOne",
          "target": "Event",
          "required": true
        }
      ]
    },
    {
      "name": "OrganizerProfile",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "contactInfo",
          "type": "text"
        }
      ]
    },
    {
      "name": "AttendeeProfile",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "contactInfo",
          "type": "text"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "organizer",
      "description": "Can create events and manage tickets.",
      "isDefault": false
    },
    {
      "name": "attendee",
      "description": "Can reserve tickets for events.",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "organizer",
      "entity": "Event",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "organizer",
      "entity": "Ticket",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "attendee",
      "entity": "Event",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "attendee",
      "entity": "Ticket",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    },
    {
      "role": "organizer",
      "entity": "OrganizerProfile",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "attendee",
      "entity": "AttendeeProfile",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "My Events",
      "route": "/my-events",
      "type": "list",
      "entity": "Event",
      "access": [
        "organizer"
      ],
      "fields": [
        "name",
        "date",
        "location"
      ]
    },
    {
      "name": "Create Event",
      "route": "/events/new",
      "type": "form",
      "entity": "Event",
      "access": [
        "organizer"
      ]
    },
    {
      "name": "Edit Event",
      "route": "/events/:id/edit",
      "type": "form",
      "entity": "Event",
      "access": [
        "organizer"
      ]
    },
    {
      "name": "Event Details",
      "route": "/events/:id",
      "type": "detail",
      "entity": "Event",
      "access": [
        "organizer",
        "attendee"
      ]
    },
    {
      "name": "Book Tickets",
      "route": "/events/:id/book",
      "type": "form",
      "entity": "Ticket",
      "access": [
        "attendee"
      ]
    },
    {
      "name": "My Tickets",
      "route": "/my-tickets",
      "type": "list",
      "entity": "Ticket",
      "access": [
        "attendee"
      ],
      "fields": [
        "event.name",
        "type",
        "quantity"
      ]
    },
    {
      "name": "Attendee List",
      "route": "/events/:id/attendees",
      "type": "list",
      "entity": "Ticket",
      "access": [
        "organizer"
      ],
      "fields": [
        "attendeeProfile.name",
        "attendeeProfile.contactInfo",
        "type",
        "quantity"
      ],
      "requiresPlan": "premium"
    },
    {
      "name": "Organizer Profile",
      "route": "/profile/organizer",
      "type": "form",
      "entity": "OrganizerProfile",
      "access": [
        "organizer"
      ]
    },
    {
      "name": "Attendee Profile",
      "route": "/profile/attendee",
      "type": "form",
      "entity": "AttendeeProfile",
      "access": [
        "attendee"
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": [
        "basicEventCreation",
        "ticketReservation"
      ]
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "featuredEventPlacement",
        "attendeeListManagement"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumFeaturesGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Attendee List"
        ],
        "features": [
          "featuredEventPlacement",
          "attendeeListManagement"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "eventOwnership",
      "entity": "Event"
    },
    {
      "type": "ownership",
      "id": "ticketOwnership",
      "entity": "Ticket"
    },
    {
      "type": "ownership",
      "id": "organizerProfileOwnership",
      "entity": "OrganizerProfile"
    },
    {
      "type": "ownership",
      "id": "attendeeProfileOwnership",
      "entity": "AttendeeProfile"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
